400: //*******************************************************************
401: axis_word_pack u_pack (
402:     .clk         (user_clk      ),
403:     .rst         (aurora_rst    ),
404:     .in_data     (pump_fwd_data ),
405:     .in_valid    (pump_fwd_en   ),
406:     .m_tdata     (tx_tdata      ),
407:     .m_tkeep     (tx_tkeep      ),
408:     .m_tlast     (tx_tlast      ),
409:     .m_tvalid    (tx_tvalid     ),
410:     .m_tready    (tx_tready     ),
411:     .o_frame_cnt (pack_frames   ),
412:     .o_overflow  (pack_ovf      )
413: );
414: 
415: //*******************************************************************
416: // 解包：Aurora RX 64bit → 8bit
417: //*******************************************************************
418: axis_word_unpack u_unpack (
419:     .clk         (user_clk      ),
420:     .rst         (aurora_rst    ),
421:     .s_tdata     (rx_tdata      ),
422:     .s_tkeep     (rx_tkeep      ),
423:     .s_tlast     (rx_tlast      ),
424:     .s_tvalid    (rx_tvalid     ),
425:     .out_data    (unpack_data   ),
426:     .out_valid   (unpack_en     ),
427:     .o_byte_cnt  (unpack_bytes  ),
428:     .o_frame_cnt (unpack_frames ),
429:     .o_overflow  (unpack_ovf    ),
430:     .o_stall_cnt (unpack_stall  )
431: );
432: 
433: //*******************************************************************
434: // 帧泵 B：user_clk → eth_rxc（回 RGMII TX）
435: //*******************************************************************
436: frame_fifo_pump u_pump_rev (
437:     .wr_clk       (user_clk      ),
438:     .wr_rst_n     (~aurora_rst   ),
439:     .wr_data      (unpack_data   ),
440:     .wr_en        (unpack_en     ),
441:     .rd_clk       (gmii_rx_clk   ),
442:     .rd_rst_n     (sys_rst_n     ),
443:     .rd_data      (pump_rev_data ),
444:     .rd_en        (pump_rev_en   ),
445:     .wr_frame_cnt (pump_rev_wr   ),
446:     .wr_drop_cnt  (pump_rev_drop ),
447:     .rd_frame_cnt (pump_rev_rd   )
448: );
449: 
450: `ifdef P8_TX_DIRECT
451: // ===== 交叉验证变体（P8_TX_DIRECT）=====
452: //   TX 直连：与官方 39 / project_6（已验证能通的"网口版"）的数据通路完全一致。
453: //   Aurora 仍在设计里（链路照常建立、ILA 照常可抓），只是不进数据通路。
454: //   判据：ping/UDP 通 => RX 侧没坏，坏在"栈TX→泵A→打包→Aurora→解包→泵B"这条绕行；
455: //         仍不通 => RX 侧确实坏（与 ILA 抓到的字节损坏一致），需回到板级/实现层查。
456: assign rgmii_txd_i   = stack_txd;
457: assign rgmii_tx_en_i = stack_tx_en;
458: `else
459: assign rgmii_txd_i   = pump_rev_data;
460: assign rgmii_tx_en_i = pump_rev_en;
461: `endif
462: 
463: //*******************************************************************
464: // 观测 LED
465: //   T22 (led_loop) : Aurora RX 收到数据（粘滞）
466: //   T23 (led_link) : channel_up
467: //*******************************************************************
468: reg led_loop_r;
469: always @(posedge user_clk) begin
470:     if (aurora_rst) led_loop_r <= 1'b0;
471:     else if (rx_tvalid) led_loop_r <= 1'b1;
472: end
473: assign led_loop = led_loop_r;
474: assign led_link = channel_up;
475: 
476: //*******************************************************************
477: // ILA 探针（脚本化调试核插入）
478: //*******************************************************************
479: // user_clk 域
480: (* mark_debug = "true" *) wire [63:0] dbg_rx_tdata  = rx_tdata;
481: (* mark_debug = "true" *) wire [7:0]  dbg_rx_tkeep  = rx_tkeep;
482: (* mark_debug = "true" *) wire        dbg_rx_tvalid = rx_tvalid;
483: (* mark_debug = "true" *) wire        dbg_rx_tlast  = rx_tlast;
484: (* mark_debug = "true" *) wire [63:0] dbg_tx_tdata  = tx_tdata;
485: (* mark_debug = "true" *) wire        dbg_tx_tvalid = tx_tvalid;
486: (* mark_debug = "true" *) wire [15:0] dbg_up_bytes  = unpack_bytes;
487: (* mark_debug = "true" *) wire [15:0] dbg_up_frames = unpack_frames;
488: (* mark_debug = "true" *) wire        dbg_up_ovf    = unpack_ovf;
489: (* mark_debug = "true" *) wire [15:0] dbg_up_stall  = unpack_stall;
490: (* mark_debug = "true" *) wire [15:0] dbg_pk_frames = pack_frames;
491: (* mark_debug = "true" *) wire        dbg_pk_ovf    = pack_ovf;
492: (* mark_debug = "true" *) wire        dbg_ch_up     = channel_up;
493: (* mark_debug = "true" *) wire        dbg_lane_up   = lane_up;
494: (* mark_debug = "true" *) wire        dbg_hard_err  = hard_err;
495: (* mark_debug = "true" *) wire        dbg_soft_err  = soft_err;
496: // 注意域归属: u_pump_rev 的**写侧**在 user_clk 域（只有读侧在 eth_rxc 域），
497: // 故这两个计数器必须挂在 user_clk 域的 ILA 上；挂到 eth_rxc 域的 ILA 会形成
498: // 未同步的跨域采样路径（首轮 WNS=-2.639 ns 的元凶之一），抓到也是亚稳态值。
499: (* mark_debug = "true" *) wire [15:0] dbg_prev_wr   = pump_rev_wr;
500: (* mark_debug = "true" *) wire [15:0] dbg_prev_drop = pump_rev_drop;
501: // eth_rxc 域
502: (* mark_debug = "true" *) wire [15:0] dbg_pfwd_wr   = pump_fwd_wr;
503: (* mark_debug = "true" *) wire [15:0] dbg_pfwd_drop = pump_fwd_drop;
504: (* mark_debug = "true" *) wire [7:0]  dbg_stack_txd = stack_txd;
505: (* mark_debug = "true" *) wire        dbg_stack_txen= stack_tx_en;
506: // eth_rxc 域 · **接收侧**可见性（2026-09-10 加：排查"PC 发的包到底进没进 FPGA"）
507: //   gmii_rx_dv   : PHY→FPGA 的 GMII 接收有效（有它 = 网线上的帧真的进来了）
508: //   arp_rx_done  : 官方栈成功解析出一个 ARP 帧（有它 = 数据没被 CRC/格式判掉）
509: //   udp/icmp_rec_done : UDP / ICMP 解析完成
510: (* mark_debug = "true" *) wire        dbg_gmii_rx_dv   = gmii_rx_dv;
511: (* mark_debug = "true" *) wire [7:0]  dbg_gmii_rxd     = gmii_rxd;
512: (* mark_debug = "true" *) wire        dbg_arp_rx_done  = arp_rx_done;
513: (* mark_debug = "true" *) wire        dbg_arp_rx_type  = arp_rx_type;
514: (* mark_debug = "true" *) wire        dbg_udp_rec_done = rec_pkt_done;
515: (* mark_debug = "true" *) wire        dbg_icmp_rec_done= icmp_rec_pkt_done;
516: (* mark_debug = "true" *) wire [15:0] dbg_rec_byte_num = rec_byte_num;
517: (* mark_debug = "true" *) wire [15:0] dbg_udp_src_port = udp_src_port;   // P8: 回显目标端口
518: 
519: endmodule

