{"code":"const r = await tools.pwsh({ command: `
Write-Host '=== prj8 vs prj6 eth stack RTL 逐字节对差 ==='
$dirs = @('arp','icmp','udp','gmii_to_rgmii')
foreach($d in $dirs){
  $p6 = Get-ChildItem \"D:\\FPGA\\project_6\\rtl\\$d\" -Filter *.v -EA SilentlyContinue
  $p8 = Get-ChildItem \"D:\\FPGA\\project_8\\rtl\\$d\" -Filter *.v -EA SilentlyContinue
  foreach($f in $p8){
    $m = $p6 | Where-Object { $_.Name -eq $f.Name }
    if($m){ $h6=(Get-FileHash $m.FullName MD5).Hash; $h8=(Get-FileHash $f.FullName MD5).Hash; $same = ($h6 -eq $h8); Write-Host ('{0}/{1}  same={2}' -f $d,$f.Name,$same) }
    else { Write-Host ('{0}/{1}  [prj6 无此文件]' -f $d,$f.Name) }
  }
}
Write-Host ''
Write-Host '=== prj8 顶层 vs prj6 顶层 ==='
Write-Host ('prj6 top: projectrtl\\eth_udp_loop.v  (注意目录名)')
Write-Host '=== XDC 对差 ==='
$x6 = Get-Content 'D:\\FPGA\\project_6\\eth_udp_loop.xdc' -Raw
$x8 = Get-Content 'D:\\FPGA\\project_8\\xdc\\aurora_udp_bridge.xdc' -Raw
Write-Host '--- prj6 xdc 全文 ---'
Write-Host $x6
`, description: "Byte-compare prj6 vs prj8 stack RTL and XDC" });
console.log(r.stdout.text);","description":"Compare prj6 vs prj8 RTL and XDC"}

