136: //时序电路描述状态输出,解析以太网数据
137: always @(posedge clk or negedge rst_n) begin
138:     if(!rst_n) begin
139:         skip_en <= 1'b0;
140:         error_en <= 1'b0;
141:         cnt <= 5'd0;
142:         des_mac <= 48'd0;
143:         eth_type <= 16'd0;
144:         des_ip <= 32'd0;
145:         ip_head_byte_num <= 6'd0;
146:         udp_byte_num <= 16'd0;
147:         data_byte_num <= 16'd0;
148:         data_cnt <= 16'd0;
149:         rec_en <= 1'b0;
150:         rec_data <= 32'd0;
151:         rec_pkt_done <= 1'b0;
152:         rec_byte_num <= 16'd0;
153:         rec_src_port <= 16'd1234;
154:     end
155:     else begin
156:         skip_en <= 1'b0;
157:         error_en <= 1'b0;  
158:         rec_pkt_done <= 1'b0;
159:         case(next_state)
160:             st_idle : begin
161:                 if((gmii_rx_dv == 1'b1) && (gmii_rxd == 8'h55)) 
162:                     skip_en <= 1'b1;
163:             end
164:             st_preamble : begin
165:                 if(gmii_rx_dv) begin                         //解析前导码
166:                     cnt <= cnt + 5'd1;
167:                     if((cnt < 5'd6) && (gmii_rxd != 8'h55))  //7个8'h55  
168:                         error_en <= 1'b1;
169:                     else if(cnt==5'd6) begin
170:                         cnt <= 5'd0;
171:                         if(gmii_rxd==8'hd5)                  //1个8'hd5
172:                             skip_en <= 1'b1;
173:                         else
174:                             error_en <= 1'b1;    
175:                     end  
176:                 end  
177:             end
178:             st_eth_head : begin
179:                 if(gmii_rx_dv) begin
180:                     cnt <= cnt + 5'b1;
181:                     if(cnt < 5'd6) 
182:                         des_mac <= {des_mac[39:0],gmii_rxd}; //目的MAC地址
183:                     else if(cnt == 5'd12) 
184:                         eth_type[15:8] <= gmii_rxd;          //以太网协议类型
185:                     else if(cnt == 5'd13) begin
186:                         eth_type[7:0] <= gmii_rxd;
187:                         cnt <= 5'd0;
188:                         //判断MAC地址是否为开发板MAC地址或者公共地址
189:                         if(((des_mac == BOARD_MAC) ||(des_mac == 48'hff_ff_ff_ff_ff_ff))
190:                        && eth_type[15:8] == ETH_TYPE[15:8] && gmii_rxd == ETH_TYPE[7:0])            
191:                             skip_en <= 1'b1;
192:                         else
193:                             error_en <= 1'b1;
194:                     end        
195:                 end  
196:             end
197:             st_ip_head : begin
198:                 if(gmii_rx_dv) begin
199:                     cnt <= cnt + 5'd1;
200:                     if(cnt == 5'd0)
201:                         ip_head_byte_num <= {gmii_rxd[3:0],2'd0};
202: 					else if(cnt == 5'd9) begin
203:                         if(gmii_rxd != UDP_TYPE) begin
204:                             //如果当前接收的数据不是UDP协议，停止解析数据                        
205:                             error_en <= 1'b1;               
206:                             cnt <= 5'd0;                        
207:                         end
208:                     end                   	
209:                     else if((cnt >= 5'd16) && (cnt <= 5'd18))
210:                         des_ip <= {des_ip[23:0],gmii_rxd};   //目的IP地址
211:                     else if(cnt == 5'd19) begin
212:                         des_ip <= {des_ip[23:0],gmii_rxd}; 
213:                         //判断IP地址是否为开发板IP地址
214:                         if((des_ip[23:0] == BOARD_IP[31:8])
215:                             && (gmii_rxd == BOARD_IP[7:0])) begin                           
216:                                 skip_en <=1'b1;                     
217:                                 cnt <= 5'd0;                         
218:                         end    
219:                         else begin            
220:                         //IP错误，停止解析数据                        
221:                             error_en <= 1'b1;               
222:                             cnt <= 5'd0;
223:                         end                                                  
224:                     end                          
225:                 end                                
226:             end 
227:             st_udp_head : begin
228:                 if(gmii_rx_dv) begin
229:                     cnt <= cnt + 5'd1;
230:                     if(cnt == 5'd0)                        
231:                         rec_src_port[15:8] <= gmii_rxd;   // P8: capture sender source port (high)
232:                     else if(cnt == 5'd1)                   
233:                         rec_src_port[7:0]  <= gmii_rxd;   // P8: capture sender source port (low)
234:                     if(cnt == 5'd4)
235:                         udp_byte_num[15:8] <= gmii_rxd;      //解析UDP字节长度 
236:                     else if(cnt == 5'd5)
237:                         udp_byte_num[7:0] <= gmii_rxd;
238:                     else if(cnt == 5'd7) begin
239:                         //有效数据字节长度，（UDP首部8个字节，所以减去8）
240:                         data_byte_num <= udp_byte_num - 16'd8;    
241:                         skip_en <= 1'b1;
242:                         cnt <= 5'd0;
243:                     end  
244:                 end                 
245:             end          
246:             st_rx_data : begin         
247:                 //接收数据          
248:                 if(gmii_rx_dv) begin
249:                     data_cnt <= data_cnt + 16'd1;
250: 					rec_data <= gmii_rxd;
251: 					rec_en <= 1'b1; 
252:                     if(data_cnt == data_byte_num - 16'd1) begin
253:                         skip_en <= 1'b1;                    //有效数据接收完成
254:                         data_cnt <= 16'd0;
255:                         rec_pkt_done <= 1'b1;               
256:                         rec_byte_num <= data_byte_num;
257:                     end     
258:                 end  
259:             end    
260:             st_rx_end : begin                               //单包数据接收完成   
261: 				rec_en <= 1'b0;
262:                 if(gmii_rx_dv == 1'b0 && skip_en == 1'b0)
263:                     skip_en <= 1'b1; 
264:             end    
265:             default : ;
266:         endcase                                                        
267:     end
268: end
269: 
270: endmodule
