240:                         data_byte_num <= udp_byte_num - 16'd8;    
241:                         skip_en <= 1'b1;
242:                         cnt <= 5'd0;
243:                     end  
244:                 end                 
245:             end          
246:             st_rx_data : begin         
247:                 //接收数据          
248:                 if(gmii_rx_dv) begin
249:                     data_cnt <= data_cnt + 16'd1;
250: 					rec_data <= gmii_rxd;
251: 					rec_en <= 1'b1; 
252:                     if(data_cnt == data_byte_num - 16'd1) begin
253:                         skip_en <= 1'b1;                    //有效数据接收完成
254:                         data_cnt <= 16'd0;
255:                         rec_pkt_done <= 1'b1;               
256:                         rec_byte_num <= data_byte_num;
257:                     end     
258:                 end  
259:             end    
260:             st_rx_end : begin                               //单包数据接收完成   
261: 				rec_en <= 1'b0;
262:                 if(gmii_rx_dv == 1'b0 && skip_en == 1'b0)
263:                     skip_en <= 1'b1; 
264:             end    
265:             default : ;
266:         endcase                                                        
267:     end
268: end
269: 
270: endmodule
