\`timescale 1ns/1ps
module async_fifo_2048x8b (
    input        rst,
    input        wr_clk,
    input        rd_clk,
    input  [7:0] din,
    input        wr_en,
    input        rd_en,
    output [7:0] dout,
    output       full,
    output       empty
);
    localparam AW = 11;  // 2048
    reg [7:0] mem [0:(1<<AW)-1];
    reg [AW:0] wptr = 0, rptr = 0;
    reg [7:0]  dout_r = 0;

