            mem[wptr[AW-1:0]] <= din;
            wptr <= wptr + 1'b1;
        end
    end

    always @(posedge rd_clk or posedge rst) begin
        if (rst) begin rptr <= 0; dout_r <= 0; end
        else if (rd_en && !empty) begin
            dout_r <= mem[rptr[AW-1:0]];
            rptr <= rptr + 1'b1;
        end
    end
endmodule
