{"code":"const old = `    // ---- Aurora AXIS 模型：tready 反压 + rx_tvalid 空洞 + 延迟 ----
    reg [15:0] lfsr = 16'hACE1;
    always @(posedge user_clk) lfsr <= {lfsr[14:0], lfsr[15]^lfsr[13]^lfsr[12]^lfsr[10]};
    assign tx_tready = lfsr[1] | lfsr[2];      // ~75% ready，制造反压
    // 打拍 + 偶发空洞
    reg [63:0] rx_tdata_r; reg [7:0] rx_tkeep_r; reg rx_tlast_r, rx_tvalid_r;
    always @(posedge user_clk) begin
        if (aurora_rst) begin rx_tvalid_r<=0; rx_tdata_r<=0; rx_tkeep_r<=0; rx_tlast_r<=0; end
        else begin
            rx_tvalid_r <= tx_tvalid & tx_tready & lfsr[0];  // 偶发空洞
            if (tx_tvalid & tx_tready) begin
                rx_tdata_r<=tx_tdata; rx_tkeep_r<=tx_tkeep; rx_tlast_r<=tx_tlast;
            end
        end
    end
    wire [63:0] rx_tdata=rx_tdata_r; wire [7:0] rx_tkeep=rx_tkeep_r;
    wire rx_tlast=rx_tlast_r, rx_tvalid=rx_tvalid_r;`;
const neu = `    // ---- Aurora AXIS 模型：beat FIFO（绝不丢 beat）+ 随机反压 + 随机 rx_tvalid 空洞 ----
    reg [15:0] lfsr = 16'hACE1;
    always @(posedge user_clk) lfsr <= {lfsr[14:0], lfsr[15]^lfsr[13]^lfsr[12]^lfsr[10]};
    reg [63:0] af_data [0:15]; reg [7:0] af_keep [0:15]; reg af_last [0:15];
    reg [4:0]  af_w = 5'd0, af_r = 5'd0;
    wire af_empty = (af_w == af_r);
    wire af_full  = (af_w[4] != af_r[4]) && (af_w[3:0] == af_r[3:0]);
    assign tx_tready = ~af_full & (lfsr[1] | lfsr[2]);     // 反压 + 满则停
    wire af_push = tx_tvalid & tx_tready;
    always @(posedge user_clk) begin
        if (af_push) begin
            af_data[af_w[3:0]] <= tx_tdata; af_keep[af_w[3:0]] <= tx_tkeep;
            af_last[af_w[3:0]] <= tx_tlast; af_w <= af_w + 5'd1;
        end
    end
    wire rx_pop = ~af_empty & lfsr[0];                     // 随机空洞（不丢数据）
    wire [63:0] rx_tdata = af_data[af_r[3:0]];
    wire [7:0]  rx_tkeep = af_keep[af_r[3:0]];
    wire        rx_tlast = af_last[af_r[3:0]];
    wire        rx_tvalid = rx_pop;
    always @(posedge user_clk) if (rx_pop) af_r <= af_r + 5'd1;`;
const r = await tools.edit({ file_path: "D:/FPGA/project_8/sim/tb_full_chain.v", old_string: old, new_string: neu });
console.log("edited:", JSON.stringify(r).slice(0,120));","description":"Fix Aurora model to never drop beats"}

