270: 
271:     always @(posedge eth_clk) begin
272:         if (pump_rev_en) begin
273:             out_frames[out_cnt][out_len[out_cnt]] = pump_rev_data;
274:             out_len[out_cnt] = out_len[out_cnt] + 1;
275:         end
276:         else if (out_len[out_cnt] != 0 && out_cnt < 8) begin
277:             out_cnt = out_cnt + 1;
278:         end
279:     end
280: 
281:     integer ii;
282:     initial begin
283:         for(ii=0;ii<8;ii=ii+1) begin in_len[ii]=0; out_len[ii]=0; end
284:     end
285: 
286:     // =====================================================================
287:     // 主流程
288:     // =====================================================================
289:     integer e; integer ok_frames; integer bad;
290:     initial begin
291:         sys_rst_n=0; channel_up=0;
292:         #200; sys_rst_n=1;
293:         #100; channel_up=1;
294:         #500;
295: 
296:         $display("[%0t] === TEST 1: ARP request -> ARP reply through detour ===", $time);
297:         build_arp_req(PC_MAC, PC_IP, BOARD_IP);
298:         send_frame();
299:         #8000;
300: 
301:         $display("[%0t] === TEST 2: UDP frame (16B payload) -> echo through detour ===", $time);
302:         build_eth_udp(BOARD_MAC, PC_MAC, BOARD_IP, PC_IP, 16'd5000, 16'd1234, 16);
303:         send_frame();
304:         #12000;
305: 
306:         $display("[%0t] === TEST 3: UDP frame (29B payload, 非8倍数) ===", $time);
307:         build_eth_udp(BOARD_MAC, PC_MAC, BOARD_IP, PC_IP, 16'd5001, 16'd1234, 29);
308:         send_frame();
309:         #12000;
310: 
311:         $display("[%0t] === TEST 4: UDP frame (200B payload) ===", $time);
312:         build_eth_udp(BOARD_MAC, PC_MAC, BOARD_IP, PC_IP, 16'd5002, 16'd1234, 200);
313:         send_frame();
314:         #25000;
315: 
316:         // ---- 汇总 ----
317:         #8000;
318:         $display("");
319:         $display("================ FULL-CHAIN RESULT ================");
320:         $display("stack_tx frames (detour input) : %0d", in_cnt);
321:         $display("pump_rev frames (detour output): %0d", out_cnt);
322:         $display("pump_fwd: wr=%0d drop=%0d rd=%0d", pfwd_wr, pfwd_drop, pfwd_rd);
323:         $display("pump_rev: wr=%0d drop=%0d rd=%0d", prev_wr, prev_drop, prev_rd);
324:         $display("pack: frames=%0d ovf=%0d | unpack: frames=%0d bytes=%0d ovf=%0d stall=%0d",
325:                  pk_frames, pk_ovf, up_frames, up_bytes, up_ovf, up_stall);
326:         ok_frames=0;
327:         for(e=0; e<((in_cnt<out_cnt)?in_cnt:out_cnt); e=e+1) begin
328:             if(in_len[e]==out_len[e]) begin
329:                 bad=0;
330:                 for(fi=0; fi<in_len[e]; fi=fi+1) begin
331:                     if(in_frames[e][fi]!==out_frames[e][fi]) begin
332:                         bad=bad+1;
333:                         if(bad<=3) $display("  frame%0d byte%0d: in=%02x out=%02x", e, fi, in_frames[e][fi], out_frames[e][fi]);
334:                     end
335:                 end
336:                 if(bad==0) begin ok_frames=ok_frames+1; $display("frame%0d: MATCH len=%0d", e, in_len[e]); end
337:                 else           $display("frame%0d: MISMATCH len=%0d/%0d badbytes=%0d", e, in_len[e], out_len[e], bad);
338:             end
339:             else $display("frame%0d: LEN MISMATCH in=%0d out=%0d", e, in_len[e], out_len[e]);
340:         end
341:         $display("--------------------------------------------------");
342:         $display("MATCHED %0d / %0d frames", ok_frames, in_cnt);
343:         if(ok_frames==in_cnt && in_cnt>=3 && pfwd_drop==0 && prev_drop==0 && pk_ovf==0 && up_ovf==0)
344:             $display("*** PASS: detour preserves stack frames byte-for-byte ***");
345:         else
346:             $display("*** FAIL ***");
347:         $display("===================================================");
348:         $finish;
349:     end
350: 
351:     // 超时兜底
352:     initial begin
353:         #500000;
354:         $display("TIMEOUT"); $finish;
355:     end
356: 
357: endmodule

