=== ila_capture_rx.tcl ===
  1: # =============================================================================
  2: # ila_capture_rx.tcl - 一次性: 武装 ILA -> 打流量 -> 导出 CSV (2026-09-10)
  3: #   ILA0 @ user_clk : dbg_rx_tvalid      (Aurora 有没有把帧送回来)
  4: #   ILA1 @ eth_rxc  : dbg_gmii_rx_dv     (PC 的包有没有进 FPGA)
  5: # 必须在同一 batch 会话内完成: 退出 batch 会解除武装 -> No data to upload
  6: # =============================================================================
  7: set ltx {D:/FPGA/project_8/scripts/probes.ltx}
  8: set out {D:/FPGA/project_8/scripts}
  9: set py  {C:\\Users\\15266\\AppData\\Local\\Python\\pythoncore-3.14-64\\python.exe}
 10: 
 11: open_hw_manager
 12: connect_hw_server
 13: open_hw_target
 14: set dev [lindex [get_hw_devices] 0]
 15: current_hw_device $dev
 16: puts "DEVICE = [get_property NAME $dev]"
 17: catch { set_property PROBES.FILE      $ltx $dev }
 18: catch { set_property FULL_PROBES.FILE $ltx $dev }
 19: refresh_hw_device -update_hw_probes true $dev
 20: 
 21: proc arm_one {ila sig} {
 22:     set nm [get_property NAME $ila]
 23:     set cn "?"
 24:     catch { set cn [get_property CELL_NAME $ila] }
 25:     set pr [get_hw_probes -of_objects $ila -filter "NAME =~ \"*$sig*\""]
 26:     if {[llength $pr] == 0} { puts "  $nm ($cn): NO PROBE $sig"; return 0 }
 27:     catch { set_property TRIGGER_COMPARE_VALUE {eq1'b1} $pr }
 28:     catch { set_property TRIGGER_POSITION 256 $ila }
 29:     if {[catch { run_hw_ila $ila } e]} { puts "  $nm ($cn): ARM FAIL: $e"; return 0 }
 30:     puts "  $nm ($cn): ARMED on $sig"
 31:     return 1
 32: }
 33: puts "== ARM =="
 34: foreach ila [get_hw_ilas -of_objects $dev] {
 35:     set cn "?"
 36:     catch { set cn [get_property CELL_NAME $ila] }
 37:     if {$cn eq "u_ila_1"} { arm_one $ila "dbg_gmii_rx_dv" } else { arm_one $ila "dbg_rx_tvalid" }
 38: }
 39: 
 40: puts "== TRAFFIC: ping =="
 41: if {[catch { exec cmd /c "ping -n 4 192.168.1.10" } e]} { puts "  $e" } else { puts "  ping ok" }
 42: puts "== TRAFFIC: udp_verify =="
 43: if {[catch { exec cmd /c "cd /d D:\\FPGA\\project_8 && \"$py\" scripts\\udp_verify.py" } e]} { puts "  $e" } else { puts "  udp ok" }
 44: after 3000
 45: 
 46: puts "== UPLOAD =="
 47: foreach ila [get_hw_ilas -of_objects $dev] {
 48:     set cn "?"
 49:     catch { set cn [get_property CELL_NAME $ila] }
 50:     set nm [get_property NAME $ila]
 51:     if {[catch { set data [upload_hw_ila_data $ila] } e]} { puts "  $nm ($cn): UPLOAD FAIL: $e"; continue }
 52:     if {[llength $data] == 0} { puts "  $nm ($cn): NO DATA (not triggered)"; continue }
 53:     if {$cn eq "u_ila_1"} { set f $out/ila_rx_u1.csv } else { set f $out/ila_rx_u0.csv }
 54:     if {[catch { write_hw_ila_data -force -csv_file $f $data } e]} { puts "  $nm ($cn): CSV FAIL: $e" } else { puts "  $nm ($cn): -> $f" }
 55: }
 56: puts "CAPTURE_RX_DONE"

