// rgmii_rx_fix.v -- RGMII RX with robust sampling phase (project_8, 2026-09-17)
//
// 背景（判别实验 + ILA 实证，2026-09-17）：
//   官方例程位流在本板上 ping 6/6 全通 => 板级硬件/PHY/网线/网卡全部健康。
//   prj8 位流 ILA 抓包：前导码/广播MAC 完好，跳变字节出现"只丢1不加1"的子集损伤
//   => 采样沿压在数据位边界上。官方 RTL 用 BUFIO 钟 IDDRE1（插入延迟 ~0.3ns），
//   但 .CB(~rgmii_rxc_bufio) 的 LUT 反相器使 2023.1 映射时把 BUFIO 吸收掉，
//   IDDRE1 实际挂上了 BUFGCE 全局时钟（插入 ~2ns）=> 采样点被推到位边界。
//   官方 2024 构建同样丢了 BUFIO，只是全局时钟布线恰好短一点点而"侥幸"工作。
//
// 修复（双保险，任何一个生效即恢复余量）：
//   A. 去掉 CB 的 LUT 反相器，用 IS_CB_INVERTED(1'b1) 承载反相，
//      让 BUFIO 路径得以保留 => IDDRE1 采样回到眼图中心。
//   B. 5 根 RX 线各加 FIXED IDELAYE3 500ps：即使工具仍走全局时钟，
//      数据窗右移后采样点依然落在窗内。
//
// 接口与官方 rgmii_rx 完全一致（gmii_to_rgmii 无需改动）。
//=============================================================================
module rgmii_rx(
    input              rgmii_rxc   ,
    input              rgmii_rx_ctl,
    input       [3:0]  rgmii_rxd   ,

    output             gmii_rx_clk ,
    output             gmii_rx_dv  ,
    output      [7:0]  gmii_rxd
);

parameter RX_DLY_PS = 500;          // 数据侧固定延迟(ps)，可扫

wire         rgmii_rxc_bufg ;
wire         rgmii_rxc_bufio;
wire  [1:0]  gmii_rxdv_t    ;
wire  [3:0]  rxd_dly        ;
wire         ctl_dly        ;

assign gmii_rx_clk = rgmii_rxc_bufg;
assign gmii_rx_dv  = gmii_rxdv_t[0] & gmii_rxdv_t[1];

BUFG  BUFG_inst  (.I(rgmii_rxc), .O(rgmii_rxc_bufg ));
BUFIO BUFIO_inst (.I(rgmii_rxc), .O(rgmii_rxc_bufio));

// ---- FIXED IDELAY：TIME 格式，无需 IDELAYCTRL/REFCLK ----
genvar k;
generate
    for (k = 0; k < 4; k = k + 1) begin : g_rxd_dly
        IDELAYE3 #(
            .CASCADE          ("NONE"),
            .DELAY_FORMAT     ("TIME"),
            .DELAY_SRC        ("IDATAIN"),
            .DELAY_TYPE       ("FIXED"),
            .DELAY_VALUE      (RX_DLY_PS),
            .IS_CLK_INVERTED  (1'b0),
            .IS_RST_INVERTED  (1'b0),
            .REFCLK_FREQUENCY (300.0),
            .SIM_DEVICE       ("ULTRASCALE"),
            .UPDATE_MODE      ("ASYNC")
        ) u_dly_rxd (
            .CASC_IN      (1'b0), .CASC_OUT (), .CASC_RETURN (1'b0),
            .CE           (1'b0), .CLK      (1'b0),
            .CNTVALUEIN   (5'd0), .CNTVALUEOUT (),
            .DATAIN       (1'b0),
            .EN_VTC       (1'b0),
            .IDATAIN      (rgmii_rxd[k]),
            .INC          (1'b0), .LOAD     (1'b0),
            .RST          (1'b0),
            .DATAOUT      (rxd_dly[k])
        );
    end
endgenerate

IDELAYE3 #(
    .CASCADE          ("NONE"),
    .DELAY_FORMAT     ("TIME"),
    .DELAY_SRC        ("IDATAIN"),
    .DELAY_TYPE       ("FIXED"),
    .DELAY_VALUE      (RX_DLY_PS),
    .IS_CLK_INVERTED  (1'b0),
    .IS_RST_INVERTED  (1'b0),
    .REFCLK_FREQUENCY (300.0),
    .SIM_DEVICE       ("ULTRASCALE"),
    .UPDATE_MODE      ("ASYNC")
) u_dly_ctl (
    .CASC_IN      (1'b0), .CASC_OUT (), .CASC_RETURN (1'b0),
    .CE           (1'b0), .CLK      (1'b0),
    .CNTVALUEIN   (5'd0), .CNTVALUEOUT (),
    .DATAIN       (1'b0),
    .EN_VTC       (1'b0),
    .IDATAIN      (rgmii_rx_ctl),
    .INC          (1'b0), .LOAD     (1'b0),
    .RST          (1'b0),
    .DATAOUT      (ctl_dly)
);

// ---- DDR 采样：C=BUFIO（低插入延迟），CB 反相改用参数承载（去掉 LUT）----
IDDRE1 #(
    .DDR_CLK_EDGE     ("SAME_EDGE_PIPELINED"),
    .IS_CB_INVERTED   (1'b1),
    .IS_C_INVERTED    (1'b0)
)
IDDRE1_inst (
    .Q1    (gmii_rxdv_t[0]),
    .Q2    (gmii_rxdv_t[1]),
    .C     (rgmii_rxc_bufio),
    .CB    (rgmii_rxc_bufio),
    .D     (ctl_dly),
    .R     (1'b0)
);

generate
    for (k = 0; k < 4; k = k + 1) begin : rxdata_bus
        IDDRE1 #(
            .DDR_CLK_EDGE      ("SAME_EDGE_PIPELINED"),
            .IS_CB_INVERTED    (1'b1),
            .IS_C_INVERTED     (1'b0)
        )
        IDDRE1_inst (
            .Q1                (gmii_rxd[k]),
            .Q2                (gmii_rxd[4+k]),
            .C                 (rgmii_rxc_bufio),
            .CB                (rgmii_rxc_bufio),
            .D                 (rxd_dly[k]),
            .R                 (1'b0)
        );
    end
endgenerate

endmodule
`;
