            .DELAY_VALUE      (RX_DLY_PS),
            .IS_CLK_INVERTED  (1'b0),
            .IS_RST_INVERTED  (1'b0),
            .REFCLK_FREQUENCY (300.0),
            .SIM_DEVICE       ("ULTRASCALE"),
            .UPDATE_MODE      ("ASYNC")
        ) u_dly_rxd (
            .CASC_IN      (1'b0), .CASC_OUT (), .CASC_RETURN (1'b0),
            .CE           (1'b0), .CLK      (1'b0),
            .CNTVALUEIN   (5'd0), .CNTVALUEOUT (),
            .DATAIN       (1'b0),
            .EN_VTC       (1'b0),
            .IDATAIN      (rgmii_rxd[k]),
            .INC          (1'b0), .LOAD     (1'b0),
            .RST          (1'b0),
            .DATAOUT      (rxd_dly[k])
        );
    end
endgenerate

IDELAYE3 #(
    .CASCADE          ("NONE"),
    .DELAY_FORMAT     ("TIME"),
    .DELAY_SRC        ("IDATAIN"),
    .DELAY_TYPE       ("FIXED"),
    .DELAY_VALUE      (RX_DLY_PS),
    .IS_CLK_INVERTED  (1'b0),
    .IS_RST_INVERTED  (1'b0),
    .REFCLK_FREQUENCY (300.0),
    .SIM_DEVICE       ("ULTRASCALE"),
    .UPDATE_MODE      ("ASYNC")
) u_dly_ctl (
    .CASC_IN      (1'b0), .CASC_OUT (), .CASC_RETURN (1'b0),
    .CE           (1'b0), .CLK      (1'b0),
    .CNTVALUEIN   (5'd0), .CNTVALUEOUT (),
    .DATAIN       (1'b0),
    .EN_VTC       (1'b0),
    .IDATAIN      (rgmii_rx_ctl),
    .INC          (1'b0), .LOAD     (1'b0),
    .RST          (1'b0),
    .DATAOUT      (ctl_dly)
