// ---- DDR 采样：C=BUFIO（低插入延迟），CB 反相改用参数承载（去掉 LUT）----
IDDRE1 #(
    .DDR_CLK_EDGE     ("SAME_EDGE_PIPELINED"),
    .IS_CB_INVERTED   (1'b1),
    .IS_C_INVERTED    (1'b0)
)
IDDRE1_inst (
    .Q1    (gmii_rxdv_t[0]),
    .Q2    (gmii_rxdv_t[1]),
    .C     (rgmii_rxc_bufio),
    .CB    (rgmii_rxc_bufio),
    .D     (ctl_dly),
    .R     (1'b0)
);

generate
    for (k = 0; k < 4; k = k + 1) begin : rxdata_bus
        IDDRE1 #(
            .DDR_CLK_EDGE      ("SAME_EDGE_PIPELINED"),
            .IS_CB_INVERTED    (1'b1),
            .IS_C_INVERTED     (1'b0)
        )
        IDDRE1_inst (
            .Q1                (gmii_rxd[k]),
            .Q2                (gmii_rxd[4+k]),
            .C                 (rgmii_rxc_bufio),
            .CB                (rgmii_rxc_bufio),
            .D                 (rxd_dly[k]),
            .R                 (1'b0)
        );
    end
endgenerate

endmodule

