            .IS_CLK_INVERTED  (1'b0),
            .IS_RST_INVERTED  (1'b0),
            .REFCLK_FREQUENCY (200.0),
            .SIM_DEVICE       ("ULTRASCALE"),
            .UPDATE_MODE      ("ASYNC")
        ) u_dly_rxd (
            .CASC_IN (1'b0), .CASC_OUT (), .CASC_RETURN (1'b0),
            .CE (1'b0), .CLK (1'b0),
            .CNTVALUEIN (5'd0), .CNTVALUEOUT (),
            .DATAIN (1'b0), .EN_VTC (1'b1),
            .IDATAIN (rgmii_rxd[k]),
            .INC (1'b0), .LOAD (1'b0), .RST (1'b0),
            .DATAOUT (rxd_dly[k])
        );
    end
endgenerate

IDELAYE3 #(
    .CASCADE          ("NONE"),
    .DELAY_FORMAT     ("TIME"),
    .DELAY_SRC        ("IDATAIN"),
    .DELAY_TYPE       ("FIXED"),
    .DELAY_VALUE      (RX_DLY_PS),
    .IS_CLK_INVERTED  (1'b0),
    .IS_RST_INVERTED  (1'b0),
    .REFCLK_FREQUENCY (200.0),
    .SIM_DEVICE       ("ULTRASCALE"),
    .UPDATE_MODE      ("ASYNC")
) u_dly_ctl (
    .CASC_IN (1'b0), .CASC_OUT (), .CASC_RETURN (1'b0),
    .CE (1'b0), .CLK (1'b0),
    .CNTVALUEIN (5'd0), .CNTVALUEOUT (),
    .DATAIN (1'b0), .EN_VTC (1'b1),
    .IDATAIN (rgmii_rx_ctl),
    .INC (1'b0), .LOAD (1'b0), .RST (1'b0),
    .DATAOUT (ctl_dly)
);

// ---- DDR 采样：BUFIO + IS_CB_INVERTED ----
IDDRE1 #(
    .DDR_CLK_EDGE     ("SAME_EDGE_PIPELINED"),
    .IS_CB_INVERTED   (1'b1),
    .IS_C_INVERTED    (1'b0)
)
IDDRE1_inst (
    .Q1 (gmii_rxdv_t[0]), .Q2 (gmii_rxdv_t[1]),
    .C  (rgmii_rxc_bufio), .CB (rgmii_rxc_bufio),
    .D  (ctl_dly), .R (1'b0)
);

generate
    for (k = 0; k < 4; k = k + 1) begin : rxdata_bus
        IDDRE1 #(
            .DDR_CLK_EDGE      ("SAME_EDGE_PIPELINED"),
            .IS_CB_INVERTED    (1'b1),
            .IS_C_INVERTED     (1'b0)
        )
        IDDRE1_inst (
            .Q1 (gmii_rxd[k]), .Q2 (gmii_rxd[4+k]),
            .C  (rgmii_rxc_bufio), .CB (rgmii_rxc_bufio),
            .D  (rxd_dly[k]), .R (1'b0)
        );
    end
endgenerate

endmodule

