{"code":"const NL = String.fromCharCode(10);
const cmd = [
"Start-Sleep -Seconds 12",
"$nic = Get-NetAdapter | Where-Object {$_.InterfaceDescription -match 'Realtek'}",
"Write-Host ('等待后状态: ' + $nic.Status)",
"if($nic.Status -ne 'Up'){",
"  Write-Host '尝试重启网卡强制重新协商（可能无权限）...'",
"  try { Restart-NetAdapter -Name $nic.Name -Confirm:$false -ErrorAction Stop; Start-Sleep -Seconds 8; Write-Host ('重启后: ' + (Get-NetAdapter -Name $nic.Name).Status) } catch { Write-Host ('重启失败: ' + $_.Exception.Message.Split([char]10)[0]) }",
"}",
"Get-NetAdapter | Where-Object {$_.InterfaceDescription -match 'Realtek'} | Format-Table Name, Status, LinkSpeed -AutoSize"
].join(NL);
const r = await tools.pwsh({ command: cmd, description: "Wait and force NIC renegotiation", timeoutMs: 120000 });
console.log(r.stdout.text);","description":"Wait longer and restart NIC"}

