{"code":"const NL = String.fromCharCode(10);
const cmd = [
"Write-Host '=== 官方 Aurora 例程目录 ==='",
"Get-ChildItem 'D:\\BaiduNetdiskDownload\\1_Verilog\\KU060例程' -Directory | Select-Object -ExpandProperty Name",
"Write-Host '=== 例程内搜 loopback/sfp ==='",
"$hits = Get-ChildItem 'D:\\BaiduNetdiskDownload\\1_Verilog\\KU060例程' -Recurse -Include *.v,*.xdc -ErrorAction SilentlyContinue | Select-String -Pattern 'loopback|tx_disable|rs0|rs1' -ErrorAction SilentlyContinue | Select-Object -First 15",
"$hits | ForEach-Object { $_.Path.Substring(40) + ' : ' + $_.LineNumber.ToString() + ' : ' + $_.Line.Trim().Substring(0,[Math]::Min(100,$_.Line.Trim().Length)) }"
].join(NL);
const r = await tools.pwsh({ command: cmd, description: "Search official example for loopback and SFP", timeoutMs: 120000 });
console.log(r.stdout.text);","description":"Search official examples for SFP handling"}

