            puts "  $nm ($cn, $dom): 时钟停了"
            if {$cn eq "u_ila_1"} { puts "      => PHY 尚未建立链路（网线/端口/PHY 复位）" }
        } else {
            puts "  $nm ($cn, $dom): 武装失败: $e"
        }
    } else {
        puts "  $nm ($cn, $dom): 时钟在跑"
        if {$cn eq "u_ila_1"} { puts "      => **PHY 链路已建立（PC 侧应能看到 1Gbps 连接）**" }
        catch { reset_hw_ila $ila }
