// ultrascale aurora_support file

 `timescale 1 ns / 10 ps

   (* core_generation_info = "aurora_64b66b_0,aurora_64b66b_v12_0_13,{c_aurora_lanes=1,c_column_used=left,c_gt_clock_1=GTHQ0,c_gt_clock_2=None,c_gt_loc_1=1,c_gt_loc_10=X,c_gt_loc_11=X,c_gt_loc_12=X,c_gt_loc_13=X,c_gt_loc_14=X,c_gt_loc_15=X,c_gt_loc_16=X,c_gt_loc_17=X,c_gt_loc_18=X,c_gt_loc_19=X,c_gt_loc_2=X,c_gt_loc_20=X,c_gt_loc_21=X,c_gt_loc_22=X,c_gt_loc_23=X,c_gt_loc_24=X,c_gt_loc_25=X,c_gt_loc_26=X,c_gt_loc_27=X,c_gt_loc_28=X,c_gt_loc_29=X,c_gt_loc_3=X,c_gt_loc_30=X,c_gt_loc_31=X,c_gt_loc_32=X,c_gt_loc_33=X,c_gt_loc_34=X,c_gt_loc_35=X,c_gt_loc_36=X,c_gt_loc_37=X,c_gt_loc_38=X,c_gt_loc_39=X,c_gt_loc_4=X,c_gt_loc_40=X,c_gt_loc_41=X,c_gt_loc_42=X,c_gt_loc_43=X,c_gt_loc_44=X,c_gt_loc_45=X,c_gt_loc_46=X,c_gt_loc_47=X,c_gt_loc_48=X,c_gt_loc_5=X,c_gt_loc_6=X,c_gt_loc_7=X,c_gt_loc_8=X,c_gt_loc_9=X,c_lane_width=4,c_line_rate=10.0,c_gt_type=GTHE3,c_qpll=true,c_nfc=false,c_nfc_mode=IMM,c_refclk_frequency=156.25,c_simplex=false,c_simplex_mode=TX,c_stream=false,c_ufc=false,c_user_k=false,flow_mode=None,interface_mode=Framing,dataflow_config=Duplex}" *)
(* DowngradeIPIdentifiedWarnings="yes" *)
 module aurora_64b66b_0_support_ext
  (
       //-----------------------------------------------------------------------
       // TX AXI Interface
       input  [0:63]     s_axi_tx_tdata,
       input  [0:7]      s_axi_tx_tkeep,
       input             s_axi_tx_tlast,
       input             s_axi_tx_tvalid,
       output            s_axi_tx_tready,
       //-----------------------------------------------------------------------
       // RX AXI Interface
       output [0:63]     m_axi_rx_tdata,
       output [0:7]      m_axi_rx_tkeep,
       output            m_axi_rx_tlast,
       output            m_axi_rx_tvalid,
       //-----------------------------------------------------------------------
       //-----------------------------------------------------------------------
       //-----------------------------------------------------------------------
       //-----------------------------------------------------------------------
       // GTX Serial I/O
       input              rxp,
       input              rxn,
       output             txp,
       output             txn,
       // Error Detection Interface
       output             hard_err,
       output             soft_err,
       // Status
       output             channel_up,
       output             lane_up,
       //-----------------------------------------------------------------------
       //-----------------------------------------------------------------------
       // System Interface
       output              user_clk_out,
       output              sync_clk_out,
       //-----------------------------------------------------------------------
       input              reset_pb, 
       input              gt_rxcdrovrden_in,
       input              power_down,
       input   [2:0]      loopback,
       input              pma_init,

       //-------------------- AXI4-Lite Interface -------------------------------
       //-------------------- Write Address Channel --------------------------
       input  [31:0]   s_axi_awaddr,
       input  [31:0]   s_axi_araddr,
       input  [31:0]   s_axi_wdata,
       input  [3:0]   s_axi_wstrb,
       input           s_axi_awvalid,
       input           s_axi_rready,
       output  [31:0]  s_axi_rdata,
       output          s_axi_awready,
       output          s_axi_wready,
       output          s_axi_bvalid,
       output  [1:0]   s_axi_bresp,
       output  [1:0]   s_axi_rresp,
       input           s_axi_bready,
       output          s_axi_arready,
       output          s_axi_rvalid,
       input           s_axi_arvalid,
       input           s_axi_wvalid,

       //-----------------------------------------------------------------------
       input              init_clk,
       output              link_reset_out,
       output              gt_pll_lock,
       output              sys_reset_out,


       // GTX Reference Clock Interface

       input              gt_refclk1_p,
       input              gt_refclk1_n,

       //-----------------------------------------------------------------------

       output bufg_gt_clr_out,
//------------------------------------------------------------------------------
//------------------------------------------------------------------------------
       output                 mmcm_not_locked_out,
       output              tx_out_clk,

       // ---- prj9 dual-cage: share refclk & QPLL with sibling Aurora in same quad ----
       output              refclk1_out,
       output              gt_qpllclk_quad1_out,
       output              gt_qpllrefclk_quad1_out,
       output              gt_qplllock_quad1_out,
       output              gt_qpllrefclklost_quad1_out,
       input               ext_qpllreset_in

 );
//********************************Wire Declarations**********************************

     //System Interface
       //wire                 mmcm_not_locked_out ;
       wire                 powerdown_i ;

       wire                  pma_init_i;
       wire                  pma_init_sync;

     // clock
       //(* KEEP = "TRUE" *) wire               user_clk_out;
       //(* KEEP = "TRUE" *) wire               sync_clk_out;


       wire               drp_clk_i;
       wire    [8:0] drpaddr_in_i;
       wire    [15:0]     drpdi_in_i;
       wire    [15:0]     drpdo_out_i;
       wire               drprdy_out_i;
       wire               drpen_in_i;
       wire               drpwe_in_i;


       wire    [31:0]     s_axi_awaddr_i;
       wire    [31:0]     s_axi_araddr_i;
       wire    [31:0]     s_axi_wdata_i;
       wire    [31:0]     s_axi_rdata_i;
       wire    [3:0]     s_axi_wstrb_i;
       wire               s_axi_awvalid_i;
       wire               s_axi_arvalid_i;
       wire               s_axi_wvalid_i;
       wire               s_axi_rvalid_i;
       wire               s_axi_bvalid_i;
       wire    [1:0]      s_axi_bresp_i;
       wire    [1:0]      s_axi_rresp_i;
       wire               s_axi_bready_i;
       wire               s_axi_awready_i;
       wire               s_axi_arready_i;
       wire               s_axi_wready_i;
       wire               s_axi_rready_i;
       wire               link_reset_i;
       wire               sysreset_from_vio_i;
       wire               gtreset_from_vio_i;
       wire               rx_cdrovrden_i;
       wire               gt_reset_i;
       wire               gt_reset_i_tmp;

   localparam DLY_FACTOR = 16;
   reg                          bufg_gt_clr_delayed = 1'b1;
   reg [DLY_FACTOR-1:0]         bufg_gt_clr_dly_cnt = 'h0;



//---{

//---}
    wire                     refclk1_in;
    wire                     sysreset_from_support;
     wire                    tied_to_ground_i;
     wire    [280:0]          tied_to_ground_vec_i;
     wire                      tied_to_vcc_i;
     wire [2 : 0] txn_dummy;
     wire [2 : 0] txp_dummy;
     assign tied_to_ground_i             = 1'b0;
     assign tied_to_ground_vec_i         = 281'h0;
     assign tied_to_vcc_i                = 1'b1;
//------------------------------------------------------------------------------


 //*********************************Main Body of Code**********************************
     // System Interface
     assign  power_down_i      =   1'b0;
    // AXI4 Lite Interface
     assign  s_axi_awaddr_i    =  32'h0;
     assign  s_axi_wdata_i     =  16'h0;
     assign  s_axi_awvalid_i   =  1'b0;
     assign  s_axi_wvalid_i    =  1'b0;
     assign  s_axi_wstrb_i    =  'd0;
     assign  s_axi_arvalid_i   =  1'b0;
     assign  s_axi_rvalid_i    =  1'b0;


//___________________________Module Instantiations______________________________

//------------------------------------------------------------------------------
// GT common is present only when QPLL is used (i.e. speed is more than 6.5g)
//------------------------------------------------------------------------------
//                      ____________
//    qpll0/1_refclk   |            | gt_qpllclk_quad1_i    (upto 4 based upon no. of Quads)
//  ------------------>|            |------------------>
//                     |            | gt_qpllrefclk_quad1_i (upto 4 based upon no. of Quads)
//      qpll0/1_reset  |  GT Common |------------------>
//  ------------------>|            | gt_qplllock_quad1_i        --"--
//                     |            |------------------>
//  qpll0/1_lock_detclk|            | gt_qpllrefclklost_quad1_i  --"--
//  ------------------>|            |------------------>
//                     |            |
//                     |____________|
//
//
//
//------------------------------------------------------------------------------
  // add physical instance of GT ultrascale common module here
    //--------------------------------------------------------------------------
    // no. of channels are max. 4, single instance of GT Common
    //----------------------------------------------------------------------
        wire qpll1_lock_quad1_out;
        wire qpll1_refclklost1_out;
        wire gt_qpllclk_quad1_i;
        wire gt_qpllrefclk_quad1_i;
        wire gt_qpllrefclklost_quad1_i;
        wire gt_qplllock_quad1_i;

        aurora_64b66b_0_gt_common_wrapper ultrascale_gt_common_1
        (
         .qpll1_refclk                (refclk1_in),                   // input
         .qpll1_reset                 (gt_to_common_qpllreset_i | ext_qpllreset_in), // prj9: OR sibling core request
       //.qpll1_lock_detclk           (init_clk_out),                 // input
	 .qpll1_lock_detclk           (init_clk),                     // input

         .qpll1_lock                  (qpll1_lock_quad1_out),         // output
         .qpll1_outclk                (gt_qpllclk_quad1_i),           // output
         .qpll1_outrefclk             (gt_qpllrefclk_quad1_i),        // output
         .qpll1_refclklost            (qpll1_refclklost1_out)
        );

       assign gt_qplllock_quad1_i       = qpll1_lock_quad1_out;
       assign gt_qpllrefclklost_quad1_i = qpll1_refclklost1_out;

    // prj9 dual-cage shared taps
    assign refclk1_out                 = refclk1_in;
    assign gt_qpllclk_quad1_out        = gt_qpllclk_quad1_i;
    assign gt_qpllrefclk_quad1_out     = gt_qpllrefclk_quad1_i;
    assign gt_qplllock_quad1_out       = gt_qplllock_quad1_i;
    assign gt_qpllrefclklost_quad1_out = gt_qpllrefclklost_quad1_i;

    //----------------------------------------------------------------------
    //--------------------------------------------------------------------------
    //--------------------------------------------------------------------------
    //--------------------------------------------------------------------------

//------------------------------------------------------------------------------

 //--- Instance of GT Ultrascale differential buffer ---------//


  IBUFDS_GTE3 IBUFDS_GTE3_refclk1 
  (
    .I     (gt_refclk1_p),
    .IB    (gt_refclk1_n),
    .CEB   (1'b0),
    .O     (refclk1_in),
    .ODIV2 ()
