    .gt_qpllrefclklost_shared (sh_qpllrefclklost),
    .gt_to_common_qpllreset_out (b_qpllreset)
);

// 回显弹性 FIFO：FWFT 同步 FIFO 512x80b（fifo_generator）
fifo_80b_echo u_echo_fifo (
    .clk   (user_clk_b ),
    .srst  (aurora_rst ),
