content.arguments:
{"code":"const P = "D:/FPGA/project_9/rtl/aurora_udp_bridge.v";
const rd = await tools.read({ file_path: P });
let t = rd.lines.map(l => l.text).join("\n") + "\n";
const cnt = (s) => t.split(s).length - 1;
const rep1 = (o, n, tag) => { const c = cnt(o); if (c !== 1) throw new Error(tag + "=" + c); t = t.replace(o, n); };

// 1) 换 wire 声明
rep1(`wire [79:0] echo_din, echo_dout;
wire echo_full, echo_empty, echo_wr, echo_rd;
wire [15:0] echo_drop_cnt;`,
`wire [7:0]  echo_byte;                 // prj9 修复: B 回显改整帧存储转发(unpack→pack)
wire        echo_byte_en;
wire [15:0] echo_b_rx_frames, echo_b_tx_frames, echo_b_ovf;`);

// 2) 换回显 shimming 逻辑（assign 块 + 丢包计数 + FIFO 实例 → unpack/pack 级联）
rep1(`assign echo_din      = {7'b0, b_rx_tlast, b_rx_tkeep, b_rx_tdata};
assign echo_wr       = b_rx_tvalid & ~echo_full;
assign b_tx_tdata    = echo_dout[63:0];
assign b_tx_tkeep    = echo_dout[71:64];
assign b_tx_tlast    = echo_dout[72];
assign b_tx_tvalid   = ~echo_empty;
assign echo_rd       = b_tx_tvalid & b_tx_tready;

// 回显丢包计数（FIFO 满才丢 —— 匹配速率下物理上不应发生，供 ILA 观测）
reg [15:0] echo_drop_r;
always @(posedge user_clk_b) begin
    if (aurora_rst)                    echo_drop_r <= 16'd0;
    else if (b_rx_tvalid & echo_full)  echo_drop_r <= echo_drop_r + 16'd1;
end
assign echo_drop_cnt = echo_drop_r;`,
`// 根因修复(2026-09-20): 裸 FWFT FIFO 直通会在 B.RX 帧中间隙时把 B.TX 抽干
// → Aurora TX 帧中欠载 → 64b/66b 帧协议违例 → TX 楔死(实测: ping 20/20 后 UDP
//   连发 2 帧即全路径永久楔死)。改用 unpack→pack 级联: pack 整帧缓存后连续拍出,
//   保证 B.TX 每帧无间隙 —— 与 prj8 第一根因(A 侧)同解, 模块复用零新逻辑。
axis_word_unpack u_unpack_b (
    .clk         (user_clk_b      ),
    .rst         (aurora_rst      ),
    .s_tdata     (b_rx_tdata      ),
    .s_tkeep     (b_rx_tkeep      ),
    .s_tlast     (b_rx_tlast      ),
    .s_tvalid    (b_rx_tvalid     ),
    .out_data    (echo_byte       ),
    .out_valid   (echo_byte_en    ),
    .o_byte_cnt  (                ),
    .o_frame_cnt (echo_b_rx_frames),
    .o_overflow  (                ),
    .o_stall_cnt (                )
);

axis_word_pack u_pack_b (
    .clk         (user_clk_b       ),
    .rst         (aurora_rst       ),
    .in_data     (echo_byte        ),
    .in_valid    (echo_byte_en     ),
    .m_tdata     (b_tx_tdata       ),
    .m_tkeep     (b_tx_tkeep       ),
    .m_tlast     (b_tx_tlast       ),
    .m_tvalid    (b_tx_tvalid      ),
    .m_tready    (b_tx_tready      ),
    .o_frame_cnt (echo_b_tx_frames ),
    .o_overflow  (echo_b_ovf       )
);`);

// 3) 删 fifo_80b_echo 实例
rep1(`// 回显弹性 FIFO：FWFT 同步 FIFO 512x80b（fifo_generator）
fifo_80b_echo u_echo_fifo (
    .clk   (user_clk_b ),
    .srst  (aurora_rst ),
    .din   (echo_din   ),
    .wr_en (echo_wr    ),
    .full  (echo_full  ),
    .dout  (echo_dout  ),
    .rd_en (echo_rd    ),
    .empty (echo_empty )
);
`, ``);

// 4) 调试探针改挂新计数器
rep1(`(* mark_debug = "true" *) wire [15:0] dbg_echo_drop   = echo_drop_cnt;`,
`(* mark_debug = "true" *) wire [15:0] dbg_echo_b_tx   = echo_b_tx_frames;
(* mark_debug = "true" *) wire [15:0] dbg_echo_b_ovf  = echo_b_ovf;`);

await tools.write({ file_path: P, content: t });
console.log("顶层回显路径已改为 unpack→pack 级联");
const NL = String.fromCharCode(10);
const cmd = [
"Get-Process -Name vivado -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue",
"cd D:\\FPGA\\project_9",
"& 'D:\\Xilinx\\Vivado\\2023.1\\bin\\vivado.bat' -mode batch -source scripts\\build_debug.tcl -notrace > build9f.log 2>&1",
"Write-Host 'DONE9F'"
].join(NL);
const r = await tools.pwsh({ command: cmd, description: "Rebuild with store-and-forward echo", run_in_background: true });
console.log("build jobId:", r.jobId);","description":"Replace echo FIFO with store-and-forward"}

