{"code":"const NL = String.fromCharCode(10);
const cmd = [
"Write-Host '=== phase1.csv 原始头部 ==='",
"Get-Content D:\\FPGA\\project_9\\scripts\\ila_wedge_phase1.csv -TotalCount 4"
].join(NL);
const r0 = await tools.pwsh({ command: cmd, description: "Check phase1 CSV raw content", timeoutMs: 60000 });
console.log(r0.stdout.text);

// 阶段3脚本: ILA1 触发于 gmii_rx_dv —— ping 期间帧到底进没进 FPGA
const L = [];
L.push("set ltx {D:/FPGA/project_9/scripts/probes.ltx}",
"set out {D:/FPGA/project_9/scripts}",
"open_hw_manager", "connect_hw_server", "open_hw_target",
"set dev [lindex [get_hw_devices] 0]", "current_hw_device $dev",
"catch { set_property PROBES.FILE $ltx $dev }",
"catch { set_property FULL_PROBES.FILE $ltx $dev }",
"refresh_hw_device -update_hw_probes true $dev",
"set ila1 [lindex [get_hw_ilas -of_objects $dev] 1]",
"set pr [get_hw_probes -of_objects $ila1 -filter {NAME =~ \"*gmii_rx_dv*\"}]",
"set_property TRIGGER_COMPARE_VALUE {eq1'b1} $pr",
"run_hw_ila $ila1",
"puts \"PHASE3: ILA1 armed on gmii_rx_dv\"",
"catch { exec cmd /c \"ping -n 4 -w 1200 192.168.1.10\" } pout",
"after 2500",
"set d [upload_hw_ila_data $ila1]",
"write_hw_ila_data -force -csv_file $out/ila_wedge_phase3.csv $d",
"puts \"PHASE3: SAVED\"",
"puts \"WEDGE_CAP3_DONE\"");
await tools.write({ file_path: "D:/FPGA/project_9/scripts/ila_cap_wedge3.tcl", content: L.join("\n") + "\n" });
const cmd2 = [
"cd D:\\FPGA\\project_9",
"& 'D:\\Xilinx\\Vivado\\2023.1\\bin\\vivado.bat' -mode batch -source scripts\\ila_cap_wedge3.tcl -notrace > ila_wedge3.log 2>&1",
"Select-String -Path ila_wedge3.log -Pattern 'PHASE3|triggered|WEDGE_CAP3_DONE|ERROR' | ForEach-Object { $_.Line.Trim() }"
].join(NL);
const r = await tools.pwsh({ command: cmd2, description: "Check if frames reach FPGA during wedge", timeoutMs: 300000 });
console.log(r.stdout.text);","description":"Capture RX ingress during wedged pings"}

