{"code":"const P = "D:/FPGA/project_9/rtl/frame_fifo_pump.v";
const rd = await tools.read({ file_path: P });
let t = rd.lines.map(l => l.text).join("\n") + "\n";
const cnt = (s) => t.split(s).length - 1;
const rep1 = (o, n, tag) => { const c = cnt(o); if (c !== 1) throw new Error(tag + "=" + c); t = t.replace(o, n); };

// 1) 声明区: 加 frm_dropping
rep1(`reg             hs_busy;                // frame in flight (handshake pending)`,
`reg             hs_busy;                // frame in flight (handshake pending)
reg             frm_dropping;           // C22: 当前帧按"忙时丢弃"处理(整帧不进 RAM)`);

// 2) 满标志公式修正(根因修复)
rep1(`assign wr_bin_next = wr_bin + 1'b1;
assign wr_full = (wr_bin_next[AW] != rd_ptr_g_s2[AW]) &&
                 (wr_bin_next[AW-1] != rd_ptr_g_s2[AW-1]);
assign wr_valid = wr_en && !wr_full;`,
`assign wr_bin_next = wr_bin + 1'b1;
// C22 根因修复(2026-09-20): 原式把**二进制** wr_bin_next 与**格雷码** rd_ptr_g_s2
// 逐位混比, 在指针回绕(累计字节跨 2048)后永久伪满 → 写侧拒收一切帧
// (板上: 25 帧后 ping/UDP 全灭; 仿真: 40 帧只完成 24, 16 帧无声消失)。
// 改为标准 Cummings 格雷满判: 写指针下一拍的格雷码 == 读指针格雷码高两位取反。
wire [AW:0] wr_ptr_g_nxt = bin2gray(wr_bin_next);
assign wr_full = (wr_ptr_g_nxt == {~rd_ptr_g_s2[AW:AW-1], rd_ptr_g_s2[AW-2:0]});
// C22: 忙时的帧整帧不进 RAM(帧原子性) —— 否则丢弃帧的字节仍会推走写指针,
// 与读侧"恰好读 rd_len 字节"失配, 指针永久错位。frm_dropping 保证释放若发生在
// 某丢弃帧中间, 该帧仍完整丢弃而非半截进 RAM。
assign wr_valid = wr_en && !wr_full && !hs_busy && !frm_dropping;`);

// 3) 写侧 FSM: busy 分支字节计数用 wr_en(不是 wr_valid, 因为被门控了), 加 dropping 粘滞
rep1(`    if(!wr_rst_n) begin
        hs_busy <= 1'b0; wr_dv_d <= 1'b0; wr_cnt <= 16'd0;
        frame_len_mb <= 16'd0; wr_done_t <= 1'b0;
        wr_frame_cnt <= 16'd0; wr_drop_cnt <= 16'd0;
        rd_done_t_s1 <= 1'b0; rd_done_t_s2 <= 1'b0; rd_done_t_ack <= 1'b0;
    end`,
`    if(!wr_rst_n) begin
        hs_busy <= 1'b0; frm_dropping <= 1'b0; wr_dv_d <= 1'b0; wr_cnt <= 16'd0;
        frame_len_mb <= 16'd0; wr_done_t <= 1'b0;
        wr_frame_cnt <= 16'd0; wr_drop_cnt <= 16'd0;
        rd_done_t_s1 <= 1'b0; rd_done_t_s2 <= 1'b0; rd_done_t_ack <= 1'b0;
    end`);

rep1(`        if(wr_valid)
            wr_cnt <= wr_cnt + 16'd1;
        if(!hs_busy) begin
            if(wr_en_fall && wr_cnt != 16'd0) begin
                frame_len_mb <= wr_cnt;
                wr_done_t    <= ~wr_done_t;     // frame available -> toggle
                hs_busy      <= 1'b1;
                wr_frame_cnt <= wr_frame_cnt + 16'd1;
            end
            if(wr_en_fall)
                wr_cnt <= 16'd0;
        end
        else begin
            // handshake pending: incoming frames dropped (counted)
            if(wr_en_fall && wr_cnt != 16'd0) begin
                wr_drop_cnt <= wr_drop_cnt + 16'd1;
                wr_cnt <= 16'd0;
            end
            if(rd_done_t_s2 != rd_done_t_ack)
                hs_busy <= 1'b0;                // frame fully drained -> release
        end`,
`        if(wr_valid)
            wr_cnt <= wr_cnt + 16'd1;
        if(!hs_busy && !frm_dropping) begin
            if(wr_en_fall && wr_cnt != 16'd0) begin
                frame_len_mb <= wr_cnt;
                wr_done_t    <= ~wr_done_t;     // frame available -> toggle
                hs_busy      <= 1'b1;
                wr_frame_cnt <= wr_frame_cnt + 16'd1;
            end
            if(wr_en_fall)
                wr_cnt <= 16'd0;
        end
        else begin
            // handshake pending(或释放落在丢弃帧中间): 整帧丢弃, 计数用 wr_en
            // (wr_valid 已被门控, 字节不进 RAM, 只计数供丢弃判定)
            if(wr_en && wr_dv_d != wr_en) begin end // (no-op, 保持结构)
            if(wr_en)
                wr_cnt <= wr_cnt + 16'd1;
            if(wr_en && !wr_dv_d)
                frm_dropping <= 1'b1;
            if(wr_en_fall) begin
                if(wr_cnt != 16'd0)
                    wr_drop_cnt <= wr_drop_cnt + 16'd1;
                wr_cnt       <= 16'd0;
                frm_dropping <= 1'b0;
            end
            if(rd_done_t_s2 != rd_done_t_ack && !frm_dropping)
                hs_busy <= 1'b0;                // frame fully drained -> release
        end`);

await tools.write({ file_path: P, content: t });
console.log("frame_fifo_pump.v 已修复(C22)");
// 顶层级: 泵A/泵B 复位对称化(全部 ~aurora_rst)
const PT = "D:/FPGA/project_9/rtl/aurora_udp_bridge.v";
const rdt = await tools.read({ file_path: PT });
let tt = rdt.lines.map(l => l.text).join("\n") + "\n";
const cntt = (s) => tt.split(s).length - 1;
const rep1t = (o, n, tag) => { const c = cntt(o); if (c !== 1) throw new Error(tag + "=" + c); tt = tt.replace(o, n); };
rep1t(`frame_fifo_pump u_pump_fwd (
    .wr_clk       (gmii_rx_clk   ),
    .wr_rst_n     (sys_rst_n     ),`,
`frame_fifo_pump u_pump_fwd (
    .wr_clk       (gmii_rx_clk   ),
    .wr_rst_n     (~aurora_rst   ),   // C22: 与读侧对称, 否则链路抖动只复位读侧 -> 指针失配`);
rep1t(`    .rd_clk       (gmii_rx_clk   ),
    .rd_rst_n     (sys_rst_n     ),
    .rd_data      (pump_rev_data ),`,
`    .rd_clk       (gmii_rx_clk   ),
    .rd_rst_n     (~aurora_rst   ),   // C22: 与写侧对称
    .rd_data      (pump_rev_data ),`);
await tools.write({ file_path: PT, content: tt });
console.log("顶层复位对称化完成");
// 重新仿真(含 40 帧基础 + 200 帧压力 + 背靠背重叠帧)
const NL = String.fromCharCode(10);
const cmd = [
"cd D:\\FPGA\\project_9\\sim",
"(Get-Content pump_tb.v) -replace 'integer total_frames = 40;','integer total_frames = 200;' -replace 'repeat \\(50\\) @\\(posedge wr_clk\\);','repeat (10) @(posedge wr_clk);' | Set-Content pump_tb_stress.v",
"& 'D:\\Xilinx\\Vivado\\2023.1\\bin\\xvlog.bat' pump_tb.v pump_tb_stress.v ..\\rtl\\frame_fifo_pump.v > sim_new.log 2>&1",
"& 'D:\\Xilinx\\Vivado\\2023.1\\bin\\xelab.bat' -debug off pump_tb -s sim_new_a >> sim_new.log 2>&1",
"& 'D:\\Xilinx\\Vivado\\2023.1\\bin\\xelab.bat' -debug off pump_tb_stress -s sim_new_b >> sim_new.log 2>&1",
"& 'D:\\Xilinx\\Vivado\\2023.1\\bin\\xsim.bat' sim_new_a -runall >> sim_new.log 2>&1",
"& 'D:\\Xilinx\\Vivado\\2023.1\\bin\\xsim.bat' sim_new_b -runall >> sim_new.log 2>&1",
"Select-String -Path sim_new.log -Pattern 'RESULT|WEDGE|ALL_ACCOUNTED|ERROR' | ForEach-Object { $_.Line.Trim() }"
].join(NL);
const r = await tools.pwsh({ command: cmd, description: "Resimulate fixed pump both paces", timeoutMs: 420000 });
