"& 'D:\\Xilinx\\Vivado\\2023.1\\bin\\xvlog.bat' pump_tb.v pump_tb_stress.v ..\\rtl\\frame_fifo_pump.v > sim_new.log 2>&1",
"& 'D:\\Xilinx\\Vivado\\2023.1\\bin\\xelab.bat' -debug off pump_tb -s sim_new_a >> sim_new.log 2>&1",
"& 'D:\\Xilinx\\Vivado\\2023.1\\bin\\xelab.bat' -debug off pump_tb_stress -s sim_new_b >> sim_new.log 2>&1",
"& 'D:\\Xilinx\\Vivado\\2023.1\\bin\\xsim.bat' sim_new_a -runall >> sim_new.log 2>&1",
"& 'D:\\Xilinx\\Vivado\\2023.1\\bin\\xsim.bat' sim_new_b -runall >> sim_new.log 2>&1",
