// C21 修复(2026-09-17): rd_empty 必须用当前 rd_bin，不能用 rd_bin_next。
//   原式 (bin2gray(rd_bin_next)==wr_ptr_g_s2) 是"提前一拍判空"：当读指针追到
//   与写指针持平（rd_bin=末字节地址）时，rd_bin_next 已等于 wr_ptr，于是把
//   **每帧最后一字节**误判为空而拒读（板上实测：第二帧恒少 1 字节、rd_frame_cnt
//   停在 1、FSM 永久卡死）。本泵是"整帧先写满再读"，读期间写指针稳定，
//   用 rd_bin 判空安全：rd_bin 追上 wr_ptr 才为空，末字节允许读出。
assign rd_empty = (bin2gray(rd_bin) == wr_ptr_g_s2);

always @(posedge rd_clk or negedge rd_rst_n) begin
    if(!rd_rst_n) begin
        rd_bin <= 0; rd_ptr_g <= 0;
        wr_ptr_g_s1 <= 0; wr_ptr_g_s2 <= 0;
    end
    else begin
        wr_ptr_g_s1 <= wr_ptr_g;
        wr_ptr_g_s2 <= wr_ptr_g_s1;
        if(rd_en_i && !rd_empty) begin
            rd_bin   <= rd_bin_next;
            rd_ptr_g <= bin2gray(rd_bin_next);
        end
    end
end

// FIFO read data capture (registered, 1-cycle latency, strobed)
always @(posedge rd_clk) begin
    if(rd_en_i && !rd_empty)
        ram_dout <= ram[rd_bin[AW-1:0]];
end

always @(posedge rd_clk) begin
    ram_dout_v <= rd_en_i && !rd_empty;
end

// pump FSM: issue exactly rd_len reads, present exactly rd_len gapless bytes
always @(posedge rd_clk or negedge rd_rst_n) begin
    if(!rd_rst_n) begin
        st <= S_IDLE; rd_cnt_i <= 16'd0; rd_cnt_o <= 16'd0; rd_len <= 16'd0;
        rd_en_i <= 1'b0;
        rd_data <= 8'd0; rd_en <= 1'b0;
        rd_frame_cnt <= 16'd0; rd_done_t <= 1'b0;
        wr_done_t_s1 <= 1'b0; wr_done_t_s2 <= 1'b0;
        // NOTE: ram_dout/ram_dout_v 故意不在本块复位——由上方无复位捕获块唯一驱动
        // （在此赋值 = 双时钟风格多驱动 → MDRV/GND 折叠，坑位 C17）
    end
    else begin
        wr_done_t_s1 <= wr_done_t;
        wr_done_t_s2 <= wr_done_t_s1;

        case(st)
            S_IDLE: begin
                rd_en <= 1'b0;
                if(wr_done_t_s1 != wr_done_t_s2) begin   // new frame available
                    rd_len   <= frame_len_mb;            // mailbox stable (4-phase)
                    rd_cnt_i <= 16'd0;
                    rd_cnt_o <= 16'd0;
                    rd_en_i  <= 1'b1;                    // prime first read
                    st       <= S_PUMP;
                end
            end
            S_PUMP: begin
                // output pipeline: (ram_dout, ram_dout_v) -> (rd_data, rd_en)
                rd_data <= ram_dout;
                rd_en   <= ram_dout_v;
                if(rd_en) begin                          // byte presented this cycle
                    rd_cnt_o <= rd_cnt_o + 16'd1;
                    if(rd_cnt_o == rd_len - 16'd1) begin // last byte out now
                        st           <= S_IDLE;
                        rd_en        <= 1'b0;            // stop after this cycle
                        rd_frame_cnt <= rd_frame_cnt + 16'd1;
                        rd_done_t    <= ~rd_done_t;      // ack -> release wr side
                    end
                end
                // read issuing: exactly rd_len strobes
                if(rd_cnt_i < rd_len - 16'd1)
                    rd_en_i <= 1'b1;
                else
                    rd_en_i <= 1'b0;
                if(rd_en_i)
                    rd_cnt_i <= rd_cnt_i + 16'd1;
            end
        endcase
    end
end

endmodule

//=============================================================================
// aurora_udp_bridge.v — Aurora-UDP 数据级桥顶层（project_9 双笼版：A(Y11,X1Y11)↔B(Y9,X1Y9) 真光链路）
//
// 数据流（数据级 64b/66b 验证）:
//   PC --RJ45(GE1,RGMII)--> [以太网栈] --回显帧--> 帧泵(CDC) --> 打包(8→64)
//      --> Aurora 64b/66b TX --> SFP+ 真光链路(loopback=3'b000) --> Aurora RX
//      --> 解包(64→8) --> 帧泵(CDC) --> RGMII TX --> PC
//
// 判据: PC 脚本比对回显 payload == 发送 payload（数据必穿过 64b/66b 编解码才回得来）
//
// 关键设计:
//   - Aurora 仅插在「栈 TX → PC」单向路径；PC→栈 直连 RGMII（回显帧 dst=PC_MAC 不重入栈）
//   - 双向帧泵跨 eth_rxc(125M, PHY 晶振) ↔ user_clk(~151.5M, GT 恢复钟)
//   - 复位: reset_pb 同步于 init_clk；pma_init 上电脉冲（128 级移位，例程同款）
//   - DRP AXI4-Lite 悬空（例程同款，仅需常量输入）
// 来源: 官方 39 以太网栈 + aurora 例程共享逻辑（shared_logic/）+ project_7 帧泵
//=============================================================================
module aurora_udp_bridge (
    // ---- RGMII GE1 (PC front-end) ----
    input              sys_rst_n ,
    input              key       ,
    input              eth_rxc   ,
    input              eth_rx_ctl,
    input       [3:0]  eth_rxd   ,
    output             eth_txc   ,
    output             eth_tx_ctl,
    output      [3:0]  eth_txd   ,
    output             eth_rst_n ,
    // ---- GT (Aurora 64b/66b, X1Y11 = SFPA) ----
    input              gt_refclk_p,
    input              gt_refclk_n,
    input              init_clk_p ,
    input              init_clk_n ,
    input              sfp_rx_p   ,
    input              sfp_rx_n   ,
    output             sfp_tx_p   ,
    output             sfp_tx_n   ,
    output             sfp_tx_disable,
    output             sfp_rs0    ,
    output             sfp_rs1    ,
    // ---- GT-B (Aurora 64b/66b 第二通道, X1Y9 = 光口Y9 通道B) ----
    input              sfpb_rx_p  ,
    input              sfpb_rx_n  ,
    output             sfpb_tx_p  ,
    output             sfpb_tx_n  ,
    output             sfpb_tx_disable,
    output             sfpb_rs0   ,
    output             sfpb_rs1   ,
    // ---- 观测 LED ----
    output             led_loop   ,
    output             led_link
);

//parameter define (official values)
parameter  BOARD_MAC = 48'h00_11_22_33_44_55;
parameter  BOARD_IP  = {8'd192,8'd168,8'd1,8'd10};
parameter  DES_MAC   = 48'hff_ff_ff_ff_ff_ff;
parameter  DES_IP    = {8'd192,8'd168,8'd1,8'd102};

//*******************************************************************
// 以太网栈侧连线（eth_rxc 域）
//*******************************************************************
wire          gmii_rx_clk, gmii_rx_dv, gmii_tx_clk;
wire [7:0]    gmii_rxd;
wire [7:0]    stack_txd;                  // 栈 TX（eth_ctrl 输出）→ 帧泵
wire          stack_tx_en;
wire [7:0]    rgmii_txd_i;                // 帧泵回来 → RGMII TX
wire          rgmii_tx_en_i;

wire          arp_gmii_tx_en; wire [7:0] arp_gmii_txd;
wire          arp_rx_done, arp_rx_type;
wire [47:0]   src_mac; wire [31:0] src_ip;
wire          arp_tx_en, arp_tx_type;
wire [47:0]   des_mac; wire [31:0] des_ip;
wire          arp_tx_done;
wire          icmp_gmii_tx_en; wire [7:0] icmp_gmii_txd;
wire          icmp_rec_pkt_done, icmp_rec_en;
