wire          tx_start_en;
wire [7:0]    rec_data, tx_data;
wire          rec_en, tx_req;

assign icmp_tx_start_en = icmp_rec_pkt_done;
assign icmp_tx_byte_num = icmp_rec_byte_num;
assign tx_start_en = rec_pkt_done;
assign tx_byte_num = rec_byte_num;
