{"code":"const P = "D:/FPGA/project_9/rtl/frame_fifo_pump.v";
const rd = await tools.read({ file_path: P });
let t = rd.lines.map(l => l.text).join("\n") + "\n";
const cnt = (s) => t.split(s).length - 1;
if (cnt(`            if(rd_done_t_s2 != rd_done_t_ack && !frm_dropping)
                hs_busy <= 1'b0;                // frame fully drained -> release`) !== 1) throw new Error("anchor");
t = t.replace(`            if(rd_done_t_s2 != rd_done_t_ack && !frm_dropping)
                hs_busy <= 1'b0;                // frame fully drained -> release`,
`            // C22b: 释放不得被 frm_dropping 门控——释放窗口只有一拍, 若恰逢丢弃帧
            // 中途会被永久错过(仿真: 40 帧只完成 1)。半帧防护由 frm_dropping 单独
            // 保证(它直到帧尾才清), hs_busy 无需参与。
            if(rd_done_t_s2 != rd_done_t_ack)
                hs_busy <= 1'b0;                // frame fully drained -> release`);
// 顺手删掉那行无意义 no-op
if (cnt(`            if(wr_en && wr_dv_d != wr_en) begin end // (no-op, 保持结构)`) !== 1) throw new Error("noop");
t = t.replace(`            if(wr_en && wr_dv_d != wr_en) begin end // (no-op, 保持结构)\n`, "");
await tools.write({ file_path: P, content: t });
console.log("C22b 修正完成");
const NL = String.fromCharCode(10);
const cmd = [
"cd D:\\FPGA\\project_9\\sim",
"Remove-Item xsim.dir -Recurse -Force -ErrorAction SilentlyContinue",
"& 'D:\\Xilinx\\Vivado\\2023.1\\bin\\xvlog.bat' pump_tb.v pump_tb_stress.v ..\\rtl\\frame_fifo_pump.v > sim_v3.log 2>&1",
